<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
import UiIcon from './UiIcon.vue'
import {ApiError,type createApi} from './api'
import type {Locale} from './i18n'
import {commandKey} from './deposit'
import {taskText,type TaskTextKey} from './task-text'
import {readTaskDraft,saveTaskDraft,taskOutcome,recoverTaskClaim,type TaskDraft} from './task-flow'
const props=defineProps<{service:ReturnType<typeof createApi>;locale:Locale;userUid:string}>()
const emit=defineEmits<{back:[];unauthorized:[]}>()
const w=(key:TaskTextKey)=>taskText(props.locale,key)
type Item={id:string;kind:string;level:number;amount:string;status:string;earned_at?:string;claimed_at?:string|null}
type Level={level:number;threshold_amount:string;upgrade_reward:string}
type TeamLevel={level:number;direct_count:number;investment_threshold:string;upgrade_reward:string}
type Config={levels:Level[];team_levels?:TeamLevel[]}
type Row={id:string;kind:string;level:number;amount:string;status:string;threshold:string;direct?:number}
const config=ref<Config>(),items=ref<Item[]>([]),busy=ref(false),loaded=ref(false),storageBlocked=ref(false),notice=ref<TaskTextKey|null>(null),draft=ref<TaskDraft|null>(null)
const storageKey='task-claim:'+props.userUid
let disposed=false
const tier=(level:number)=>w((['silver','gold','platinum','diamond','king'] as const)[level-1]!)
const teamName=(level:number)=>w(('team'+level) as TaskTextKey)
const rows=computed(()=>config.value?.levels.map(level=>({...items.value.find(x=>x.kind==='vip_upgrade'&&x.level===level.level)??{id:'',kind:'vip_upgrade',level:level.level,amount:level.upgrade_reward,status:'locked'},threshold:level.threshold_amount}))??[])
const teamRows=computed<Row[]>(()=>(config.value?.team_levels??[]).map(level=>{const item=items.value.find(x=>x.kind==='team_leader'&&x.level===level.level);return {id:item?.id??'',kind:'team_leader',level:level.level,amount:item?.amount??level.upgrade_reward,status:item?.status??'locked',threshold:level.investment_threshold,direct:level.direct_count}}))
const historicalRows=computed(()=>items.value.filter(x=>x.kind==='direct_recharge'))
const amountLabel=(amount:string)=>amount.replace(/\.00$/,'')
function fail(e:unknown){if(e instanceof ApiError&&e.status===401)emit('unauthorized');notice.value='error'}
function dropDraft(){if(!draft.value)return;const value=readTaskDraft(localStorage.getItem(storageKey),props.userUid);if(value?.key!==draft.value.key||value.id!==draft.value.id)throw Error('changed');localStorage.removeItem(storageKey);draft.value=null}
async function cachedRequest<T>(key:string,path:string,onChange?:(value:T)=>void):Promise<T>{if(typeof props.service.requestCached==='function')return props.service.requestCached<T>(key,path,undefined,{},undefined,{},value=>{if(!disposed)onChange?.(value)});return props.service.request<T>(path)}
async function read(){const [c,r]=await Promise.all([cachedRequest<Config>(`user:${props.userUid}:tasks.config`,'/tasks/config',value=>{config.value=value}),cachedRequest<{items:Item[];next_before:string|null}>(`user:${props.userUid}:tasks`,'/tasks',value=>{items.value=value.items})]);if(disposed)return;config.value=c;items.value=r.items;loaded.value=true}
async function reconcile(){if(!draft.value)return;try{const d=draft.value,result=await recoverTaskClaim(d,()=>props.service.request('/business-results/task.claim/'+d.key),(id,key)=>disposed?Promise.reject(Error('left')):props.service.request('/tasks/'+id+'/claim',{}, {'Idempotency-Key':key}),e=>e instanceof ApiError&&e.status===404);if(disposed)return;const outcome=taskOutcome(result,d.id);if(outcome==='success'){await read();if(disposed)return;const row=items.value.find(x=>x.id===d.id);if(row?.status!=='claimed'){notice.value='pending';return}dropDraft();notice.value='success'}else if(outcome==='failed'){await read();if(!disposed){dropDraft();notice.value='error'}}else notice.value='pending'}catch(e){if(!disposed){if(e instanceof ApiError&&e.status===401)emit('unauthorized');notice.value='pending'}}}
async function load(){if(busy.value)return;busy.value=true;notice.value=null;try{storageBlocked.value=false;try{const raw=localStorage.getItem(storageKey);draft.value=readTaskDraft(raw,props.userUid);if(raw&&!draft.value){storageBlocked.value=true;notice.value='storage'}}catch{storageBlocked.value=true;notice.value='storage'}await read();if(!disposed&&!storageBlocked.value)await reconcile()}catch(e){if(!disposed)fail(e)}finally{if(!disposed)busy.value=false}}
async function claim(row:{id:string;status:string}){if(busy.value||storageBlocked.value||draft.value||row.status!=='earned'||!row.id)return;busy.value=true;notice.value=null;const d={uid:props.userUid,id:row.id,key:commandKey()};try{try{saveTaskDraft(localStorage,storageKey,d);draft.value=d}catch{notice.value='storage';return}if(disposed)return;await props.service.request('/tasks/'+row.id+'/claim',{}, {'Idempotency-Key':d.key});props.service.invalidateCached?.(`user:${props.userUid}:tasks`);props.service.invalidateCached?.(`user:${props.userUid}:tasks.config`);if(!disposed)await reconcile()}catch(e){if(!disposed){if(e instanceof ApiError&&e.status===401)emit('unauthorized');notice.value='pending';await reconcile()}}finally{if(!disposed)busy.value=false}}
onMounted(()=>load());onUnmounted(()=>{disposed=true})
</script>
<template><div class="reference-surface reference-task"><header class="fixed top-0 w-full z-50 bg-surface/80 backdrop-blur-xl shadow-[0_1px_8px_rgba(0,0,0,0.04)] pt-safe"><div class="h-14 px-margin-sm flex items-center justify-between relative"><button class="w-11 h-11 flex items-center justify-center -ml-space-xs text-on-surface hover:text-primary transition-colors" :aria-label="w('back')" @click="emit('back')" type="button"><UiIcon name="arrow_back" :size="22" class="material-symbols-outlined text-[22px]"/></button><div class="absolute left-1/2 -translate-x-1/2 flex items-center justify-center pointer-events-none"><h1 class="font-headline-sm text-headline-sm text-on-surface tracking-tight truncate max-w-[200px]">{{w('title')}}</h1></div><div class="flex items-center gap-space-xs"></div></div></header><main class="flex flex-col relative w-full pt-14 pb-safe bg-surface min-h-screen"><div class="flex flex-col w-full pb-10"><div class="px-margin-sm flex flex-col gap-space-md"><p v-if="notice" role="alert">{{w(notice)}}</p><button v-if="!busy&&(!loaded||notice)" @click="load" type="button">{{w(draft?'check':'retry')}}</button><template v-if="loaded&&config"><section v-if="rows.length" class="flex flex-col gap-space-sm" id="section-vip"><h2 class="text-center font-body-md text-body-md">{{w('memberLevel')}}</h2><div class="flex flex-col gap-2.5"><template v-for="row in rows" :key="row.level"><template v-if="row.status!=='locked'"><div class="p-3.5 bg-surface-container-lowest rounded-xl shadow-sm flex items-center justify-between gap-3 border border-primary/10"><div class="flex items-center gap-3 min-w-0"><div class="w-10 h-10 rounded-full bg-primary-fixed/40 flex items-center justify-center shrink-0 text-primary font-bold"><span class="font-display text-[15px]">V{{row.level}}</span></div><div class="flex flex-col min-w-0"><div class="flex items-center gap-2"><span class="font-body-md text-body-md font-bold text-on-surface truncate">VIP {{row.level}} {{tier(row.level)}} <span data-investment-threshold="true" class="block mt-0.5 text-[12px] font-normal whitespace-normal">{{w('investment')}}{{amountLabel(row.threshold)}}USDT</span></span></div><span class="font-body-sm text-body-sm text-on-surface-variant mt-0.5">{{w('upgrade')}}<strong class="font-label-numeric-md text-on-surface font-semibold">{{row.amount}}USDT</strong></span></div></div><div class="shrink-0"><button v-if="row.status==='earned'" class="inline-flex items-center justify-center px-3.5 py-1.5 rounded-full font-body-sm text-body-sm font-semibold shadow-sm transition-all active:scale-95 bg-primary text-on-primary min-w-[76px] text-center hover:bg-on-primary-fixed-variant" :disabled="busy||storageBlocked||row.status!=='earned'||!!draft" @click="claim(row)" type="button">{{w('claim')}}</button><span v-else class="inline-flex items-center justify-center px-3.5 py-1.5 rounded-full font-body-sm text-body-sm font-medium bg-surface-container text-outline min-w-[76px] text-center">{{w('claimed')}}</span></div></div></template><template v-else><div class="p-3.5 bg-surface-container-lowest rounded-xl shadow-sm flex items-center justify-between gap-3 opacity-80"><div class="flex items-center gap-3 min-w-0"><div class="w-10 h-10 rounded-full bg-surface-container flex items-center justify-center shrink-0 text-outline"><UiIcon name="lock" :size="20" class="material-symbols-outlined text-[20px]"/></div><div class="flex flex-col min-w-0"><div class="flex items-center gap-2"><span class="font-body-md text-body-md font-medium text-outline truncate">VIP {{row.level}} {{tier(row.level)}} <span data-investment-threshold="true" class="block mt-0.5 text-[12px] font-normal whitespace-normal">{{w('investment')}}{{amountLabel(row.threshold)}}USDT</span></span></div><span class="font-body-sm text-body-sm text-outline mt-0.5">{{w('upgrade')}} {{row.amount}}USDT</span></div></div><div class="shrink-0"><span class="inline-flex items-center justify-center px-3.5 py-1.5 rounded-full bg-surface-container text-outline font-body-sm text-body-sm min-w-[76px] text-center">{{w('locked')}}</span></div></div></template></template></div></section><section v-if="teamRows.length" class="flex flex-col gap-space-sm" id="section-team-leader"><h2 class="text-center font-body-md text-body-md">{{w('teamLevel')}}</h2><div class="flex flex-col gap-2.5"><template v-for="row in teamRows" :key="'team-'+row.level"><template v-if="row.status!=='locked'"><div class="p-3.5 bg-surface-container-lowest rounded-xl shadow-sm flex items-center justify-between gap-3 border border-primary/10"><div class="flex items-center gap-3 min-w-0"><div class="w-10 h-10 rounded-full bg-primary-fixed/40 flex items-center justify-center shrink-0 text-primary font-bold"><span class="font-display text-[15px]">T{{row.level}}</span></div><div class="flex flex-col min-w-0"><div class="flex items-center gap-2"><span class="font-body-md text-body-md font-bold text-on-surface truncate">{{teamName(row.level)}} <span data-team-threshold="true" class="block mt-0.5 text-[12px] font-normal whitespace-normal">{{w('teamCount')}}{{row.direct}}{{w('personUnit')}}</span><span data-team-investment="true" class="block text-[12px] font-normal whitespace-normal">{{w('teamInvestment')}}{{amountLabel(row.threshold)}}USDT</span></span></div><span class="font-body-sm text-body-sm text-on-surface-variant mt-0.5">{{w('teamUpgrade')}}<strong class="font-label-numeric-md text-on-surface font-semibold">{{row.amount}}USDT</strong></span></div></div><div class="shrink-0"><button v-if="row.status==='earned'" class="inline-flex items-center justify-center px-3.5 py-1.5 rounded-full font-body-sm text-body-sm font-semibold shadow-sm transition-all active:scale-95 bg-primary text-on-primary min-w-[76px] text-center hover:bg-on-primary-fixed-variant" :disabled="busy||storageBlocked||row.status!=='earned'||!!draft" @click="claim(row)" type="button">{{w('claim')}}</button><span v-else class="inline-flex items-center justify-center px-3.5 py-1.5 rounded-full font-body-sm text-body-sm font-medium bg-surface-container text-outline min-w-[76px] text-center">{{w('claimed')}}</span></div></div></template><template v-else><div class="p-3.5 bg-surface-container-lowest rounded-xl shadow-sm flex items-center justify-between gap-3 opacity-80"><div class="flex items-center gap-3 min-w-0"><div class="w-10 h-10 rounded-full bg-surface-container flex items-center justify-center shrink-0 text-outline"><UiIcon name="lock" :size="20" class="material-symbols-outlined text-[20px]"/></div><div class="flex flex-col min-w-0"><div class="flex items-center gap-2"><span class="font-body-md text-body-md font-medium text-outline truncate">{{teamName(row.level)}} <span data-team-threshold="true" class="block mt-0.5 text-[12px] font-normal whitespace-normal">{{w('teamCount')}}{{row.direct}}{{w('personUnit')}}</span><span data-team-investment="true" class="block text-[12px] font-normal whitespace-normal">{{w('teamInvestment')}}{{amountLabel(row.threshold)}}USDT</span></span></div><span class="font-body-sm text-body-sm text-outline mt-0.5">{{w('teamUpgrade')}} {{row.amount}}USDT</span></div></div><div class="shrink-0"><span class="inline-flex items-center justify-center px-3.5 py-1.5 rounded-full bg-surface-container text-outline font-body-sm text-body-sm min-w-[76px] text-center">{{w('locked')}}</span></div></div></template></template></div></section><section v-if="historicalRows.length" class="flex flex-col gap-space-sm" id="section-historical-rewards"><h2 class="font-body-md text-body-md">{{w('historical')}}</h2><div v-for="row in historicalRows" :key="row.id" class="p-3.5 bg-surface-container-lowest rounded-xl shadow-sm flex items-center justify-between gap-3"><span class="font-body-sm text-body-sm">{{w('reward')}} {{row.amount}}USDT</span><button v-if="row.status==='earned'" type="button" :disabled="busy||storageBlocked||!!draft" @click="claim(row)" class="px-3.5 py-1.5 rounded-full bg-primary text-on-primary">{{w('claim')}}</button><span v-else class="text-outline">{{w('claimed')}}</span></div></section></template><div class="flex flex-col gap-space-sm pt-2"><div class="py-6 flex flex-col items-center justify-center text-center gap-1.5"><p class="font-body-md text-body-md font-medium text-on-surface-variant tracking-widest">{{w('brand')}}</p></div></div></div></div></main></div></template>
